    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Det væsentlige forbehold bevares: målestokken er erhvervsevne som studerende, ikke efter uddannelsen. Rubrikken kræver ikke en fuld gengivelse af alle udelukkelsesregler. Ingen meningsændrende forbehold er udeladt."
    },
